/**
 * The JavaScript port must reproduce the Python implementation's answers.
 *
 * fixtures/parity.json was generated by running the reference implementation
 * (see fixtures/generate.py). If these tests fail, the extension and the Python
 * tool disagree about what a deal is - which is the one thing that must not drift.
 */

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { buildStats, explainNoDeals, findDeals } from "../src/core/analyzer.js";
import { makeListing, normalizeWatch } from "../src/core/models.js";
import { parseItems } from "../src/core/adapters/vinted.js";
import { parseAds } from "../src/core/adapters/leboncoin.js";

const parity = JSON.parse(readFileSync(new URL("./fixtures/parity.json", import.meta.url), "utf8"));

/** Same double, or a relative tolerance for sums that accumulate differently. */
function close(actual, expected, tol = 1e-9, label = "") {
  assert.ok(
    Math.abs(actual - expected) <= tol * Math.max(1, Math.abs(expected)),
    `${label}expected ${expected}, got ${actual}`,
  );
}

function toListing(payload, marketplace = "mock") {
  return makeListing({
    marketplace,
    itemId: payload.itemId,
    title: payload.title,
    url: `https://example.invalid/${payload.itemId}`,
    price: payload.price,
    currency: payload.currency,
    condition: payload.condition,
    size: payload.size,
    brand: payload.brand,
    landedPrice: payload.landedPrice,
    favourites: payload.favourites,
    createdAt: payload.createdAt,
  });
}

test("stats match the Python implementation exactly", () => {
  assert.ok(parity.stats.length >= 8, "expected a useful number of stats cases");
  for (const c of parity.stats) {
    const stats = buildStats(c.prices, c.currency);
    const e = c.expected;
    const where = `[${c.name}] `;
    assert.equal(stats.sampleSize, e.sampleSize, `${where}sampleSize`);
    assert.equal(stats.usedSize, e.usedSize, `${where}usedSize`);
    assert.equal(stats.median, e.median, `${where}median`);
    assert.equal(stats.q1, e.q1, `${where}q1`);
    assert.equal(stats.q3, e.q3, `${where}q3`);
    assert.equal(stats.mad, e.mad, `${where}mad`);
    close(stats.mean, e.mean, 1e-9, `${where}mean `);
    if (e.lowerFence === null) assert.equal(stats.lowerFence, null, `${where}lowerFence`);
    else close(stats.lowerFence, e.lowerFence, 1e-9, `${where}lowerFence `);
  }
});

test("deal detection matches the Python implementation exactly", () => {
  assert.ok(parity.deals.length >= 4, "expected a useful number of deal cases");
  for (const c of parity.deals) {
    const where = `[${c.name}] `;
    const watch = normalizeWatch(c.watch);
    const comparables = c.pool.map((p) => toListing(p));
    const stats = buildStats(comparables.map((x) => x.price), comparables[0].currency);

    assert.equal(stats.median, c.expectedStats.median, `${where}median`);
    assert.equal(stats.usedSize, c.expectedStats.usedSize, `${where}usedSize`);
    assert.equal(stats.sampleSize, c.expectedStats.sampleSize, `${where}sampleSize`);

    const candidates = c.candidates.map((p) => toListing(p));
    const deals = findDeals(candidates, stats, watch);
    assert.deepEqual(
      deals.map((d) => d.listing.itemId),
      c.expectedDeals.map((d) => d.itemId),
      `${where}deal set`,
    );
    for (const [i, deal] of deals.entries()) {
      const expected = c.expectedDeals[i];
      close(deal.listing.price, expected.price, 1e-9, `${where}price `);
      close(deal.marketPrice, expected.marketPrice, 1e-9, `${where}marketPrice `);
      close(deal.discountPct, expected.discountPct, 1e-9, `${where}discountPct `);
      close(deal.robustZ, expected.robustZ, 1e-9, `${where}robustZ `);
    }

    // The diagnostics the UI shows when nothing is found must match too.
    const notes = explainNoDeals(candidates, stats, watch);
    assert.deepEqual(notes, c.expectedNotes, `${where}notes`);
  }
});

test("the Vinted parser matches the Python parser on a real captured payload", () => {
  const c = parity.vinted;
  const items = parseItems(c.payload, { domain: "vinted.fr" });
  assert.equal(items.length, c.expected.length);
  for (const [i, expected] of c.expected.entries()) {
    const item = items[i];
    const where = `[vinted ${expected.itemId}] `;
    assert.equal(item.itemId, expected.itemId, `${where}itemId`);
    assert.equal(item.title, expected.title, `${where}title`);
    assert.equal(item.url, expected.url, `${where}url`);
    assert.equal(item.price, expected.price, `${where}price`);
    assert.equal(item.currency, expected.currency, `${where}currency`);
    assert.equal(item.landedPrice, expected.landedPrice, `${where}landedPrice`);
    assert.equal(item.condition, expected.condition, `${where}condition`);
    assert.equal(item.brand, expected.brand, `${where}brand`);
    assert.equal(item.size, expected.size, `${where}size`);
    assert.equal(item.favourites, expected.favourites, `${where}favourites`);
  }
  // The real payload is geo-dependent: it came back in USD, never assume EUR.
  assert.equal(items[0].currency, "USD");
});

test("the leboncoin parser matches the Python parser on real captured records", () => {
  const c = parity.leboncoin;
  const items = parseAds(c.payload);
  assert.equal(items.length, c.expected.length);
  for (const [i, expected] of c.expected.entries()) {
    const item = items[i];
    const where = `[lbc ${expected.itemId}] `;
    assert.equal(item.itemId, expected.itemId, `${where}itemId`);
    assert.equal(item.title, expected.title, `${where}title`);
    assert.equal(item.url, expected.url, `${where}url`);
    assert.equal(item.price, expected.price, `${where}price`);
    assert.equal(item.currency, expected.currency, `${where}currency`);
    assert.equal(item.condition, expected.condition, `${where}condition`);
    assert.equal(item.brand, expected.brand, `${where}brand`);
    assert.equal(item.size, expected.size, `${where}size`);
    assert.equal(item.sellerType, expected.sellerType, `${where}sellerType`);
    if (expected.createdAt === null) {
      assert.equal(item.createdAt, null, `${where}createdAt`);
    } else {
      // Compared as instants: Python writes +00:00, JS writes Z.
      assert.equal(Date.parse(item.createdAt), Date.parse(expected.createdAt), `${where}createdAt`);
    }
  }
});
